#include <bits/stdc++.h>
using namespace std;

int main() {
    int w[6];
    int total = 0;
    for (int i = 0; i < 6; i++) {
        cin >> w[i];
        total += w[i];
    }

    if (total % 3 != 0) {
        cout << "N" << endl;
        return 0;
    }

    int S = total / 3;

    // Escolhe o cubo do topo (índice t), depois um par para o segundo andar
    for (int t = 0; t < 6; t++) {
        if (w[t] != S) continue;
        vector<int> rest;
        for (int i = 0; i < 6; i++) if (i != t) rest.push_back(w[i]);
        int n = rest.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (rest[i] + rest[j] == S) {
                    // os três restantes formam o primeiro andar
                    int s = 0;
                    for (int k = 0; k < n; k++)
                        if (k != i && k != j) s += rest[k];
                    if (s == S) {
                        cout << "S" << endl;
                        return 0;
                    }
                }
            }
        }
    }

    cout << "N" << endl;
    return 0;
}
